package ru.mcsa.bukkit;
import java.util.*;import org.bukkit.*;import org.bukkit.inventory.*;
public final class GeneratedLoot implements Inventory,InventoryHolder {
 private final ItemStack[] slots;private GeneratedLoot(String[] a){slots=new ItemStack[(a.length-4)/3];for(int i=0;i<slots.length;i++){int n=4+i*3;Material type=Material.matchMaterial(a[n]);if(type!=null&&!type.isAir()&&Integer.parseInt(a[n+1])>0)slots[i]=ItemStack.fromHost(type,Integer.parseInt(a[n+1]),a[n+2]);}}
 public static void run(String[] a){GeneratedLoot holder=new GeneratedLoot(a);List<ItemStack> items=new ArrayList<>();List<Integer> positions=new ArrayList<>();for(int i=0;i<holder.slots.length;i++)if(holder.slots[i]!=null){items.add(holder.slots[i]);positions.add(i);}org.bukkit.event.world.LootGenerateEvent event=new org.bukkit.event.world.LootGenerateEvent(holder,items);RuntimeState.fire(event);List<ItemStack> result=event.isCancelled()?Collections.emptyList():event.getLoot();if(result.size()>holder.slots.length)throw new IllegalArgumentException("Добыча не помещается в контейнер");Arrays.fill(holder.slots,null);for(int i=0;i<result.size();i++){int position=i<positions.size()?positions.get(i):i;while(holder.slots[position]!=null)position=(position+1)%holder.slots.length;holder.slots[position]=result.get(i).clone();}StringBuilder out=new StringBuilder();for(ItemStack item:holder.slots){out.append(item==null?"air":Ascii.lower(item.getType().name())).append('\n').append(item==null?0:item.getAmount()).append('\n').append(item==null?"":item.metadata()).append('\n');}Host.call(22,out.toString());}
 public Inventory getInventory(){return this;}public InventoryHolder getHolder(){return this;}public int getSize(){return slots.length;}public ItemStack[] getContents(){ItemStack[] copy=slots.clone();for(int i=0;i<copy.length;i++)if(copy[i]!=null)copy[i]=copy[i].clone();return copy;}public ItemStack getItem(int slot){return slots[slot]==null?null:slots[slot].clone();}public boolean contains(Material type){for(ItemStack item:slots)if(item!=null&&item.getType()==type)return true;return false;}public boolean containsAtLeast(ItemStack value,int count){for(ItemStack item:slots)if(item!=null&&item.isSimilar(value))count-=item.getAmount();return count<=0;}
 public void setItem(int slot,ItemStack value){throw new UnsupportedOperationException("В событии генерации используйте setLoot для изменения добычи");}public HashMap<Integer,ItemStack> addItem(ItemStack... values){throw new UnsupportedOperationException("В событии генерации используйте setLoot");}public HashMap<Integer,ItemStack> removeItem(ItemStack... values){throw new UnsupportedOperationException("В событии генерации используйте setLoot");}
}
